import { type ReactNode } from 'react';
type PrimitiveValue = string | number | boolean | null | undefined;
type SerializableValue = PrimitiveValue | SerializableValue[] | {
    [key: string]: SerializableValue;
};
export type SearchParamPrimitive = string | null | undefined;
export type SearchParamArray = ReadonlyArray<SearchParamValue>;
export type SearchParamObject = Readonly<{
    [name: string]: SearchParamValue;
}>;
export type SearchParamValue = SearchParamPrimitive | SearchParamArray | SearchParamObject;
export type SearchParams = Readonly<Record<string, SearchParamValue>>;
export type ExtensionContext = Record<string, SerializableValue>;
export type RouteParams = Record<string, string | undefined>;
export type RouteDefinition = {
    path: string;
    render(params: RouteParams, context: ExtensionContext): ReactNode;
};
export type RouteKey = string;
export type RoutesConfig = Record<RouteKey, RouteDefinition>;
export type Href = string;
export type HrefChangeEvent = {
    href: Href;
    options?: NavigationOptions;
    searchParams?: SearchParams;
};
export type HrefListener = (e: HrefChangeEvent) => void;
export type UnsubscribeFn = () => void;
export type MatchedRoute = {
    key: RouteKey;
    routeDefinition: RouteDefinition;
    routeParams: RouteParams;
};
export type RouteDescriptor = {
    key: RouteKey;
    params?: RouteParams;
    searchParams?: SearchParams;
};
export type NavigationOptions = Partial<{
    /**
     * When true, replaces the current history entry instead of pushing a new one.
     */
    replace: boolean;
    /**
     * When true, indicates the href update originates from the other side
     * of the Host<->Sandbox bridge (via RPC).
     */
    remote: boolean;
}>;
type SetHrefOptions = NavigationOptions & {
    /**
     * The complete search-parameter state for the next href.
     */
    searchParams?: SearchParams;
};
export type ExtensionRouter = {
    getHref(): Href;
    setHref(href: Href, options?: SetHrefOptions): void;
    listenToHref(listener: HrefListener): UnsubscribeFn;
    setRoute(config: RoutesConfig, route: RouteDescriptor, options?: NavigationOptions): void;
    createPathSegments(config: RoutesConfig, route: RouteDescriptor): string[];
    getMatchedRoute(config: RoutesConfig, href: Href): MatchedRoute | null;
    validateRoutes(config: RoutesConfig): RoutesConfig;
    getSearchParams(): SearchParams | undefined;
};
export {};
